!function(t) {
    "use strict";
    t(".switcher-toggle").on("click", function() {
        var s = t("#styles-switcher.left")
          , e = t("#styles-switcher.right");
        "-202px" === e.css("right") ? t(e).animate({
            right: "0px"
        }, 300).addClass("shadow") : t(e).animate({
            right: "-202px"
        }, 300).removeClass("shadow"),
        "-202px" === s.css("left") ? t(s).animate({
            left: "0px"
        }, 300).addClass("shadow") : t(s).animate({
            left: "-202px"
        }, 300).removeClass("shadow")
    }),
    t("#styles-switcher ul li").on("click", function() {
        var s = t(this).data("path");
        t("#color-switcher").attr("href", s),
        t(this).parent().find("li").removeClass("active"),
        t(this).addClass("active")
    })
    t("#reset-color").on("click", function() {
        t("#color-switcher").removeAttr("href"),
        t("#styles-switcher ul li").parent().find("li").removeClass("active")
        
    })
    
  t("#styles-switcher ul li").on("click", function() {
    var s = t(this).data("path"); // Get the data-path value
    console.log("Selected data-path: ", s); // Log the data-path value

    t("#color-switcher").attr("href", s); // Set the href attribute
    console.log("Updated #color-switcher href to: ", t("#color-switcher").attr("href")); // Log the new href

    t(this).parent().find("li").removeClass("active"); // Remove active class from all siblings
    t(this).addClass("active"); // Add active class to the clicked item
});





}(jQuery);
